async function shard(run,path,rows){const previous=await optional(run,`${path}.json`);if(previous){await bound(run,previous);if(previous.rows!==rows.length||previous.records_sha256!==digest(rows))throw new Error('Immutable evaluation rows changed');return previous;}let file;try{file=await receipt(run,path);const retained=[];for await(const row of readRows(run,path))retained.push(row);if(digest(retained)!==digest(rows))throw new Error('Orphan evaluation shard differs');file={...file,rows:retained.length,schema:SCHEMA};}catch(error){if(error.code!=='ENOENT')throw error;const recipe=await readJSON(run,'recipe.json');file=await writeRows(run,path,rows,{schema:SCHEMA,totalBytes:recipe.limits.totalBytes});}const record={...file,records_sha256:digest(rows)};await json(run,`${path}.json`,record);return record;}
