function requireResearch(value,name){if(value?.authority!=='NONE'||value?.adopted_catalog!==false)throw new Error(`${name} must explicitly retain authority NONE and adopted_catalog false`);}

/** Identity/count checks do not infer successful acquisition from convenient output prefixes. */
export function assessSelectedCoverage(selected,processed,missing,{expected=selected.length}={}){
  if(!Array.isArray(selected)||selected.length!==expected||new Set(selected.map(value=>value.id)).size!==expected)throw new Error('Selected coverage population differs');
  const population=new Map(selected.map(value=>[value.id,value]));const seen=new Set();
  for(const value of processed){if(!population.has(value.id)||seen.has(value.id)||population.get(value.id).cohort!==value.cohort)throw new Error('Processed coverage has unknown, duplicate or wrong-cohort IDs');seen.add(value.id);}
  for(const value of missing){if(!population.has(value.id)||seen.has(value.id)||population.get(value.id).cohort!==value.cohort||value.acquisition_status!=='TERMINAL_DOWNLOAD_FAILURE')throw new Error('Selected shortage must retain terminal failure identity');seen.add(value.id);}
  if(seen.size!==expected)throw new Error('Selected source coverage omits records');return {selected:expected,processed:processed.length,terminal_failures:missing.length};
}

export function validateNormalizedSpan(unit,normalized){
  if(!unit||typeof normalized!=='string'||!Number.isSafeInteger(unit.start)||!Number.isSafeInteger(unit.end)||unit.start<0||unit.end>normalized.length||unit.start>unit.end||typeof unit.text!=='string'||normalized.slice(unit.start,unit.end)!==unit.text||sha256(unit.text)!==unit.sha256)throw new Error('Evaluation unit text/hash differs from complete normalized source offsets');
  return {start:unit.start,end:unit.end,sha256:unit.sha256,offsets:'JavaScript UTF16 normalized-source offsets'};
}

/** Structural requirements only. No number of candidates is imposed. */
