    if(card.status!=='AGENT_DRAFT_REQUIRES_OWNER_REVIEW')throw new Error('Candidate meanings remain owner-review drafts');
    if(!text(card.contrast?.fixed_facts)||!text(card.contrast?.higher)||!text(card.contrast?.lower)||card.contrast.higher.trim()===card.contrast.lower.trim())throw new Error('Candidate requires distinct higher/lower emphasis with explicit fixed facts');
    for(const name of ['scope','counterexamples','nearest_confusions','transfer_limits'])if(!Array.isArray(card[name])||!card[name].length||card[name].some(value=>!text(typeof value==='string'?value:value?.description??value?.difference)))throw new Error(`Candidate requires explicit ${name}`);
