    for(const evidence of card.evidence){if(!text(evidence.unit_id)||!text(evidence.reason)||evidence.reason.trim().split(/\s+/u).length<8)throw new Error('Candidate evidence requires unit ID and grounded reason');references.add(evidence.unit_id);}
