  if(selected.size!==10000||manifest.requested_contracts!==10000||manifest.eligible_prefix_contracts!==10000||manifest.selected_prefix_terminal_complete!==true)throw new Error('Candidate freeze requires the complete frozen 10000-record discovery prefix');
  const committed=new Map(),failed=new Map();for await(const event of readLedger(run)){if(event.kind==='download-committed')committed.set(event.id,event);if(event.kind==='download-failed')failed.set(event.id,event);}
  const seen=new Set();for(const record of manifest.contract_records??[]){const selection=selected.get(record.id);const event=committed.get(record.id);if(!selection||seen.has(record.id)||record.cohort!==selection.cohort||!event||event.sha256!==record.raw_sha256)throw new Error('Full discovery contract coverage or raw ledger binding differs');seen.add(record.id);await bound(run,{path:event.raw_path,sha256:event.sha256,bytes:event.bytes});}
