export async function verifyEvaluationExtraction(runDir,manifest){const {freeze,study}=await verifyCandidateFreeze(runDir);if(!RESERVED.has(manifest.cohort)||manifest.freeze_sha256!==freeze.freeze_sha256||manifest.fit_access!==false)throw new Error('Evaluation extraction must bind the frozen reserve and refuse fitting');
  const name=`evaluation/${freeze.freeze_sha256.slice(0,20)}/${manifest.cohort}/extraction/manifest.json`;if(digest(strip(manifest))!==digest(await readJSON(runDir,name,{maxBytes:128*1024*1024})))throw new Error('Supplied reserve extraction differs from its complete retained manifest');
  const population=[];for await(const item of readRows(runDir,study.selection.path))if(item.cohort===manifest.cohort)population.push(item);assessSelectedCoverage(population,manifest.contracts,manifest.missing,{expected:manifest.selected});const selected=new Set(population.map(value=>value.id));const seen=new Set();for(const record of manifest.contracts){if(!selected.has(record.id)||seen.has(record.id)||record.cohort!==manifest.cohort)throw new Error('Reserved selected source coverage differs');seen.add(record.id);await verifyArtifacts(runDir,Object.values(record.lineage).filter(value=>value&&typeof value==='object'&&value.path));}
  for(const missing of manifest.missing){if(!selected.has(missing.id)||seen.has(missing.id)||missing.acquisition_status!=='TERMINAL_DOWNLOAD_FAILURE')throw new Error('Reserved source failures cannot replace selected records');seen.add(missing.id);}
  if(seen.size!==selected.size||manifest.processed!==manifest.contracts.length||manifest.selected!==selected.size)throw new Error('Evaluation manifest omits selected source records');for(const items of Object.values(manifest.shards))await verifyArtifacts(runDir,items);return {status:'VERIFIED',selected:seen.size};}

function topAcrossFamilies(list,item,count){const position=list.findIndex(existing=>existing.family_id===item.family_id);if(position>=0){if(list[position].score>item.score||list[position].score===item.score&&list[position].id.localeCompare(item.id)<=0)return;list.splice(position,1);}list.push(item);list.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));if(list.length>count)list.length=count;}
function cosine(left,right){let dot=0,a=0,b=0;for(let i=0;i<left.length;i++){dot+=left[i]*right[i];a+=left[i]*left[i];b+=right[i]*right[i];}if(!a||!b)throw new Error('Zero evaluation/query vector cannot supply cosine rank');return dot/Math.sqrt(a*b);}

/** Shared budget, contract round robin, baseline inference and fixed-centroid assignment. */
