  const selectedSet=new Set(selected.map(unit=>unit.id));if(selectedSet.size!==selected.length||selected.some(unit=>unit.partition!=='evaluation'||unit.cohort!==cohort))throw new Error('Reserve admission identity or partition differs');
  const extractionBinding=extraction.manifest_path?await receipt(runDir,extraction.manifest_path):null;if(!extractionBinding)throw new Error('Evaluation embedding needs an actual retained extraction manifest');
  const preInference={schema_version:2,status:'FROZEN_RESERVED_UNIT_SELECTION',authority:'NONE',adopted_catalog:false,freeze_sha256:freeze.freeze_sha256,cohort,extraction:extractionBinding,selected_ids:selected.map(unit=>unit.id),selected_ids_sha256:digest(selected.map(unit=>unit.id)),units:selected.length,unit_budget:freeze.unit_budgets[cohort],selection:'fixed seeded contract round robin within retained per-contract provisional units',full_sources_searchable:true,fit_access:false};await json(runDir,`${prefix}/pre-inference.json`,preInference);
