export async function* readEvaluationBatches(runDir,manifest){const {freeze}=await verifyCandidateFreeze(runDir);if(!RESERVED.has(manifest.cohort)||manifest.freeze_sha256!==freeze.freeze_sha256||manifest.fit_access!==false||manifest.rows>freeze.unit_budgets[manifest.cohort])throw new Error('Reserve vector scope/fit boundary differs');let total=0;const ids=new Set();for(const item of manifest.shards){const batch=JSON.parse(await readFile(await bound(runDir,item),'utf8'));const vectors=decoded(await readFile(await bound(runDir,batch.vectors)),384);if(batch.rows!==item.rows||batch.rows!==batch.units.length||vectors.length!==batch.rows*384||digest(batch.units.map(unit=>unit.id))!==batch.ordered_ids_sha256||batch.partition!=='evaluation'||batch.freeze_sha256!==freeze.freeze_sha256)throw new Error('Reserved vector identities, byte count or partition differ');for(const unit of batch.units){if(ids.has(unit.id)||unit.cohort!==manifest.cohort||unit.partition!=='evaluation')throw new Error('Duplicate or fit row in reserved vectors');ids.add(unit.id);}total+=batch.rows;yield {batch,rows:batch.units,vectors,dimensions:384};}if(total!==manifest.rows)throw new Error('Reserved vector manifest omits rows');}
export async function verifyEvaluationVectors(runDir,manifest){const {freeze}=await verifyCandidateFreeze(runDir);const name=`evaluation/${freeze.freeze_sha256.slice(0,20)}/${manifest.cohort}/vectors/manifest.json`;if(digest(strip(manifest))!==digest(await readJSON(runDir,name,{maxBytes:128*1024*1024})))throw new Error('Supplied reserved vectors differ from their complete retained manifest');let rows=0;for await(const batch of readEvaluationBatches(runDir,manifest))rows+=batch.rows;return {status:'VERIFIED',rows,fit_access:false};}

/** Ranking creates review work; all passages still await a separate semantic judgment. */
