  const discovery=await readJSON(runDir,freeze.inputs.discovery.path,{maxBytes:128*1024*1024});const exact=new Set(),templates=new Set();for(const record of discovery.contract_records)if(HEX.test(record.normalized_sha256??''))exact.add(record.normalized_sha256);for(const item of discovery.cache){await bound(runDir,item);const cache=await readJSON(runDir,item.path,{maxBytes:64*1024*1024});templates.add(sha256(cache.normalized_text.toLowerCase().replace(/\b\d+(?:[.,]\d+)*\b/gu,'#').replace(/\s+/gu,' ').trim()));}
  const familiar=unit=>exact.has(unit.normalized_sha256)?'FAMILIAR_EXACT_NORMALIZED_CONTRACT':templates.has(unit.template_fingerprint)?'FAMILIAR_TEMPLATE_FINGERPRINT':'UNKNOWN_NOVELTY';
  let random=[];for(const item of extraction.shards.sections){await bound(runDir,item);for await(const wrapped of readRows(runDir,item.path)){const unit=JSON.parse(wrapped.payload);const priority=digest([freeze.seed,cohort,unit.id]);random.push({id:unit.id,priority,unit,novelty:familiar(unit)});random.sort((a,b)=>a.priority.localeCompare(b.priority)||a.id.localeCompare(b.id));if(random.length>300)random.length=300;}}
  const queryVectors=freeze.query_vectors?decoded(await readFile(await bound(runDir,freeze.query_vectors)),384):new Float32Array();if(queryVectors.length!==freeze.queries.length*384)throw new Error('Frozen query count differs from retained vector bytes');const retrieved=new Map();for(const card of freeze.cards)for(const kind of ['matches','confusions'])retrieved.set(`${card.id}:${kind}`,[]);
  for await(const chunk of readEvaluationBatches(runDir,vectors))for(let index=0;index<chunk.rows.length;index++){const unit=chunk.rows[index],vector=chunk.vectors.subarray(index*384,(index+1)*384);for(const card of freeze.cards)for(const kind of ['matches','confusions']){let score=-Infinity,queryId=null;for(let query=0;query<freeze.queries.length;query++)if(freeze.queries[query].candidate_id===card.id&&freeze.queries[query].kind===kind){const actual=cosine(vector,queryVectors.subarray(query*384,(query+1)*384));if(actual>score){score=actual;queryId=freeze.queries[query].id;}}topAcrossFamilies(retrieved.get(`${card.id}:${kind}`),{id:unit.id,family_id:unit.family_id,score,query_id:queryId,unit,novelty:familiar(unit),assignment:chunk.batch.assignments[index]},kind==='matches'?50:20);}}
  const lexical=new Map(freeze.cards.map(card=>[card.id,[]]));let fullSourceScanned=0;for(const descriptor of extraction.shards.units){await bound(runDir,descriptor);let shardRows=0;for await(const wrapped of readRows(runDir,descriptor.path)){const unit=JSON.parse(wrapped.payload);if(unit.id!==wrapped.id||unit.cohort!==cohort||unit.partition!=='evaluation'||sha256(unit.text)!==unit.sha256)throw new Error('Full-source search identity or text binding differs');shardRows++;fullSourceScanned++;const words=new Set((unit.text.toLowerCase().match(/[\p{L}]{3,}/gu)??[]));for(const card of freeze.cards){let score=0,queryId=null;for(const query of freeze.queries)if(query.candidate_id===card.id&&query.kind==='matches'&&query.lexical_terms.length){const actual=query.lexical_terms.filter(term=>words.has(term)).length/query.lexical_terms.length;if(actual>score){score=actual;queryId=query.id;}}if(score>0)topAcrossFamilies(lexical.get(card.id),{id:unit.id,family_id:unit.family_id,score,query_id:queryId,unit,novelty:familiar(unit)},50);} }if(shardRows!==descriptor.rows)throw new Error('Full-source search shard omits source units');}
  const packets=[],occurrences=new Map();async function emit(id,purpose,candidateId,items,target){const rows=[];for(const [index,item]of items.entries()){occurrences.set(item.id,(occurrences.get(item.id)??0)+1);const unit=item.unit;const normalized=await readFile(await bound(runDir,unit.lineage.normalized),'utf8');validateNormalizedSpan(unit,normalized);rows.push({packet_id:`${id}:${index+1}`,unit_id:unit.id,contract_id:unit.contract_id,cohort,candidate_id:candidateId,purpose,judgment:'NOT_REVIEWED',source:{start:unit.start,end:unit.end,sha256:unit.sha256,parent_section_id:unit.parent_section_id??unit.id,lineage:unit.lineage},novelty:item.novelty,retrieval:purpose==='random'?null:{score:item.score,query_id:item.query_id,assignment:item.assignment??null,semantic_confirmation:false},family_id:unit.family_id});}const packet={schema_version:2,status:'NOT_REVIEWED',authority:'NONE',adopted_catalog:false,freeze_sha256:freeze.freeze_sha256,cohort,purpose,candidate_id:candidateId,target,count:rows.length,shortage:target-rows.length,rows,judgment_categories:RULES.categories,prompt:'Read the frozen candidate card and complete referenced source. Decide supportive, contradictory, unrelated or unclear, explaining exact source evidence and uncertainty. A retrieval rank or cluster assignment is not an answer.',human_evidence:false};const binding=await json(runDir,`${prefix}/${id}.json`,packet);packets.push({id,purpose,candidate_id:candidateId,count:rows.length,target,binding});}
  await emit('random','random',null,random,300);for(const card of freeze.cards){for(const kind of ['matches','confusions'])await emit(`${digest(card.id).slice(0,16)}-${kind}`,kind,card.id,retrieved.get(`${card.id}:${kind}`),kind==='matches'?50:20);await emit(`${digest(card.id).slice(0,16)}-full-source-lexical`,'full_source_lexical_diagnostic',card.id,lexical.get(card.id),50);}
